<?php require 'config/database.php';require 'config/app.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT * FROM tournaments WHERE tournament_id=?");$s->execute([$id]);$t=$s->fetch();if(!$t){http_response_code(404);$pageTitle='Not found';require 'includes/header.php';echo '<div class="empty section"><h2>Tournament not found</h2><a href="tournaments.php" class="btn btn-hot">Back to tournaments</a></div>';require 'includes/footer.php';exit;}$pageTitle=$t['name'];$s=$pdo->prepare("SELECT COUNT(*) FROM registrations WHERE tournament_id=? AND status IN ('confirmed','pending_payment','payment_review')");$s->execute([$id]);$used=(int)$s->fetchColumn();require 'includes/header.php';?>
<section class="detail-banner art<?=($id%3)+1?>"><span class="tag"><?=e(strtoupper($t['status']))?></span><div><div class="eyebrow">BGMI / TOURNAMENT SERIES</div><h1><?=e($t['name'])?></h1><p><?=e($t['description'])?></p></div><small>BA / <?=str_pad((string)$id,3,'0',STR_PAD_LEFT)?></small></section><div class="detail-grid section"><section class="box"><div class="eyebrow">TOURNAMENT OVERVIEW</div><h2>THE RULES OF <span>ENGAGEMENT.</span></h2><p><?=nl2br(e($t['rules']?:'Play fair, respect all participants, and follow administrator instructions.'))?></p><div class="rule-grid"><div><small>GAME MODE</small><b><?=e($t['mode'])?></b></div><div><small>SQUAD SIZE</small><b>4 players</b></div><div><small>REGISTRATION CLOSES</small><b><?=e(date('d M Y, g:i A',strtotime($t['registration_deadline'])))?></b></div><div><small>TOURNAMENT START</small><b><?=e(date('d M Y, g:i A',strtotime($t['tournament_date'])))?></b></div></div></section><aside class="box"><div class="eyebrow">YOUR ENTRY</div><div class="entry-price"><?=$t['entry_fee']>0?'₹'.number_format($t['entry_fee']):'FREE'?> <small>/ squad</small></div><div class="prize"><small>PRIZE POOL</small><b>₹<?=number_format($t['prize_pool'])?></b></div><p class="slot-label">TEAM SLOTS <b><?=min($used,(int)$t['max_teams'])?> / <?=(int)$t['max_teams']?></b></p><div class="meter"><i style="width:<?=min(100,round($used/max(1,(int)$t['max_teams'])*100))?>%"></i></div><?php if($t['status']==='open'&&strtotime($t['registration_deadline'])>time()&&$used<(int)$t['max_teams']):?><a class="btn btn-hot btn-lg w-100 mt-3" href="team-register.php?tournament_id=<?=$id?>">Register your squad ↗</a><?php else:?><button disabled class="btn btn-card w-100 mt-3">Registration unavailable</button><?php endif;?><p class="fine">Paid entries are confirmed only after payment review in this demo version.</p></aside></div><?php require 'includes/footer.php';?>
